		<?php $status = $this->pickup_status(); ?><h3><?php echo esc_html__( 'Ход синхронизации', 'walls-delivery-calc' ); ?></h3><div data-wdc-ozon-pickup-progress data-wdc-ozon-state="<?php echo esc_attr( (string) $status['state'] ); ?>"><div class="notice inline" data-wdc-ozon-progress-bar hidden><p>Импорт выполняется...</p></div><table class="widefat striped" style="max-width:760px"><tbody><tr><th>Статус</th><td data-wdc-ozon-field="state"></td></tr><tr><th>Начало</th><td data-wdc-ozon-field="started_at"></td></tr><tr><th>Последнее обновление</th><td data-wdc-ozon-field="progress_updated_at"></td></tr><tr><th>Обработано страниц</th><td data-wdc-ozon-field="page_count"></td></tr><tr><th>Получено ID ПВЗ</th><td data-wdc-ozon-field="downloaded_count"></td></tr><tr><th>Сохранено ПВЗ</th><td data-wdc-ozon-field="accepted_count"></td></tr><tr><th>Отклонено</th><td data-wdc-ozon-field="rejected_count"></td></tr><tr><th>Дубликатов</th><td data-wdc-ozon-field="duplicate_count"></td></tr><tr><th>Конфликтов</th><td data-wdc-ozon-field="conflict_count"></td></tr><tr data-wdc-ozon-error-row hidden><th>Ошибка</th><td data-wdc-ozon-field="safe_error_message"></td></tr></tbody></table><p class="description" data-wdc-ozon-stall hidden></p></div>
