		<?php $preview = $this->pickup_preview(); ?><h3><?php echo esc_html__( 'Проверка локального справочника', 'walls-delivery-calc' ); ?></h3><form method="get" style="max-width:760px"><input type="hidden" name="page" value="wdc-delivery-services"><input type="hidden" name="service" value="ozon_delivery"><input type="hidden" name="tab" value="ozon_pickup"><table class="form-table" role="presentation"><tr><th><label for="wdc_ozon_preview_latitude">Широта</label></th><td><input id="wdc_ozon_preview_latitude" name="wdc_ozon_preview_latitude" value="<?php echo esc_attr( $preview['latitude'] ); ?>" inputmode="decimal"></td></tr><tr><th><label for="wdc_ozon_preview_longitude">Долгота</label></th><td><input id="wdc_ozon_preview_longitude" name="wdc_ozon_preview_longitude" value="<?php echo esc_attr( $preview['longitude'] ); ?>" inputmode="decimal"></td></tr></table><?php submit_button( __( 'Найти ПВЗ в локальном справочнике', 'walls-delivery-calc' ), 'secondary', 'submit', false ); ?></form><?php if ( $preview['submitted'] ) : ?><p class="description"><?php echo esc_html( $preview['valid'] ? 'Показано ПВЗ в радиусе 20 км: ' . (string) count( $preview['points'] ) . '. Диагностическая выборка ограничена 20 точками. Используются только данные активного локального справочника.' : 'Введите корректную пару координат для поиска в локальном справочнике.' ); ?></p><?php if ( $preview['valid'] && array() !== $preview['points'] ) : ?><table class="widefat striped" style="max-width:960px"><thead><tr><th>ПВЗ</th><th>Адрес</th><th>Режим работы</th><th>Координаты</th></tr></thead><tbody><?php foreach ( $preview['points'] as $point ) : ?><tr><td><?php echo esc_html( (string) ( $point['name'] ?? '' ) ); ?></td><td><?php echo esc_html( (string) ( $point['address'] ?? '' ) ); ?></td><td><?php echo esc_html( (string) ( $point['schedule'] ?? '' ) ); ?></td><td><?php echo esc_html( (string) ( $point['latitude'] ?? '' ) . ', ' . (string) ( $point['longitude'] ?? '' ) ); ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?><?php endif; ?>
	<?php }
	/** @return array<string,mixed> */ public function pickup_status(): array { return $this->pickup_repository?->status() ?? array( 'state' => 'idle', 'is_running' => false, 'is_terminal' => true, 'active_count' => 0 ); }
	/** @return array{submitted:bool,valid:bool,latitude:string,longitude:string,points:array<int,array<string,string>>} */
	private function pickup_preview(): array { $latitude = trim( (string) wp_unslash( $_GET['wdc_ozon_preview_latitude'] ?? '' ) ); $longitude = trim( (string) wp_unslash( $_GET['wdc_ozon_preview_longitude'] ?? '' ) ); $submitted = array_key_exists( 'wdc_ozon_preview_latitude', $_GET ) || array_key_exists( 'wdc_ozon_preview_longitude', $_GET ); if ( ! $submitted || ! is_numeric( $latitude ) || ! is_numeric( $longitude ) || (float) $latitude < -90 || (float) $latitude > 90 || (float) $longitude < -180 || (float) $longitude > 180 || ! $this->pickup_provider instanceof OzonDeliveryPickupPointProvider ) { return array( 'submitted' => $submitted, 'valid' => false, 'latitude' => $latitude, 'longitude' => $longitude, 'points' => array() ); } $query = new CarrierPickupPointQuery( OzonDeliverySettings::CARRIER_KEY, 1, 'RU', '', (float) $latitude, (float) $longitude, new PickupCargoConstraints(), CarrierPickupPointQuery::PURPOSE_DESTINATION_PICKUP, 20, 20 ); $points = array(); foreach ( array_slice( $this->pickup_provider->search( $query ), 0, 20 ) as $point ) { $points[] = array( 'name' => (string) ( $point->raw_reference['point_name'] ?? '' ), 'address' => $point->address, 'schedule' => $point->work_time, 'latitude' => (string) $point->latitude, 'longitude' => (string) $point->longitude ); } return array( 'submitted' => true, 'valid' => true, 'latitude' => $latitude, 'longitude' => $longitude, 'points' => $points ); }
}
